export function storesFor(seed,day,state){const stores=DAY_STORES[day-1].slice();if(state?.party.some(p=>p.profile?.preferredStores?.includes('dx捕鲸堡'))&&!stores.includes('dx捕鲸堡'))stores.push('dx捕鲸堡');const offset=hash(`${seed}:stores:${day}`)%stores.length;return stores.slice(offset).concat(stores.slice(0,offset))}
