export function friendEndingMessages(state){return state.party.slice(1).map(p=>{const pool=p.profile?.events?.ending||['下次还可以再约。'],count=state.interactions.filter(e=>e.friendId===p.id).length,meals=state.history.filter(d=>d.mealFriends?.includes(p.id)).length,training=state.history.filter(d=>d.trainingFriends?.includes(p.id)).length,index=hash(`${state.seed}:ending:${p.id}:${count}`)%pool.length;const facts=p.id==='deng'?(meals?'这周饭点碰见过。下次也发地址。':'这周饭点没碰上。下次发地址。'):({xixi:`记录补上：同行训练 ${training} 天，一起吃饭 ${meals} 天。`,feifei:`健康任务碰头 ${training} 天，饭点碰头 ${meals} 天，后者很好记。`,y:`日程里空出了 ${training} 天碰头训练，还有 ${meals} 天吃饭。`,meng:`在馆里见了 ${training} 天，饭桌边见了 ${meals} 天，都挺好的。`,dai:`实践样本：一起练 ${training} 天，一起吃 ${meals} 天。有感觉吗？`,kevin:`核对过了，训练碰头 ${training} 天，吃饭 ${meals} 天。`,mystery:`这一周的画面里，训练同框 ${training} 天，饭桌同框 ${meals} 天。`}[p.id]||`一起练了 ${training} 天，吃了 ${meals} 天饭。`);return {id:p.id,name:p.name,line:[pool[index],facts,pool.length>1?pool[(index+1+hash(p.id)%(pool.length-1))%pool.length]:''].join(' ')}})}

const EPILOGUE_LINES=['居然真的坚持了一周。','第七天结束的时候，身体还没有申请离职。','体验卡的边角已经起毛，计划倒还算完整。','最后一次关上储物柜，声音和第一天差不多。人不太一样。','七天没有让生活焕然一新，只让楼梯稍微讲了点道理。','手表安静了几秒，像也在确认这件事真的发生过。','镜子没有播放胜利动画。幸好手机替它震了一下。','运动鞋还在脚上，没有变成奖杯。这很合理。','你站在门口，突然想不起第一天为什么那么紧张。','身体逐项清点完酸痛，勉强批准了本周结案。'];
