  function initWheels(){document.querySelectorAll('.number-wheel').forEach(wheel=>{const input=$(wheel.dataset.input),min=Number(wheel.dataset.min),max=Number(wheel.dataset.max),row=Number.parseFloat(getComputedStyle(wheel).getPropertyValue('--wheel-row'))||22;let selected=null,ticking=false;const sync=value=>{const next=Math.max(min,Math.min(max,value));if(selected)selected.setAttribute('aria-selected','false');selected=wheel.querySelector(`[data-value="${next}"]`);selected?.setAttribute('aria-selected','true');if(selected)wheel.setAttribute('aria-activedescendant',selected.id);if(input&&input.value!==String(next)){input.value=String(next);input.dispatchEvent(new Event('input',{bubbles:true}))}};const syncScroll=()=>sync(min+Math.round(wheel.scrollTop/row));wheel.addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{ticking=false;syncScroll()})});wheel.addEventListener('click',event=>{const item=event.target.closest('.number-wheel-item');if(item)wheel.scrollTo({top:(Number(item.dataset.value)-min)*row,behavior:'smooth'})});wheel.addEventListener('keydown',event=>{const keys={ArrowUp:-1,ArrowDown:1,PageUp:-5,PageDown:5};if(!(event.key in keys))return;event.preventDefault();const value=Math.max(min,Math.min(max,Number(input.value)+keys[event.key]));wheel.scrollTo({top:(value-min)*row,behavior:'smooth'});sync(value)});const value=Math.max(min,Math.min(max,Number(input?.value)||min));wheel.scrollTop=(value-min)*row;sync(value)})}
